    /*
     * Add to the ProductionOrders
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	BuildSchedule
     */
    public BuildSchedule addToProductionOrders( UUID parentId, ProductionOrder addTo ) {
	    LOGGER.info("handling AssignProductionOrdersToBuildScheduleEvent - " );
	    
	    BuildSchedule parentEntity = repository.findById(parentId).get();
	    ProductionOrder child = registry.project( ProductionOrder.class, addTo.getProductionOrderId());
	    
	    parentEntity.getProductionOrders().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the ProductionOrders
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	BuildSchedule
     */
	public BuildSchedule removeFromProductionOrders( UUID parentId, ProductionOrder removeFrom ) {
	    LOGGER.info("handling RemoveProductionOrdersFromBuildScheduleEvent " );
	
	    BuildSchedule parentEntity = repository.findById(parentId).get();
	    ProductionOrder child = registry.project( ProductionOrder.class, removeFrom.getProductionOrderId());
	    
	    parentEntity.getProductionOrders().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



